import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"十三、常见问题","description":"","frontmatter":{"title":"十三、常见问题"},"headers":[],"relativePath":"ch05/13.md","filePath":"ch05/13.md","lastUpdated":1789497795000}'),c={name:"ch05/13.md"};function a(i,t,n,s,l,u){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="十三、常见问题" tabindex="-1">十三、常见问题 <a class="header-anchor" href="#十三、常见问题" aria-label="Permalink to &quot;十三、常见问题&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td>所有请求 401，包括公开接口</td><td>过滤链里漏了 <code>permitAll()</code>，或 <code>anyRequest()</code> 写在了具体规则前面</td></tr><tr><td>所有 POST 返回 403 且提示看不懂</td><td>忘了 <code>csrf().disable()</code>（无状态令牌认证场景下应关掉）</td></tr><tr><td>登录了却是 403</td><td><code>getAuthorities()</code> 少了 <code>ROLE_</code> 前缀；或 <code>hasRole</code> 与 <code>hasAuthority</code> 混用（见第十一节）</td></tr><tr><td>未登录时返回 HTML 而不是 JSON</td><td>没配 <code>authenticationEntryPoint</code></td></tr><tr><td>中文提示乱码</td><td>写响应流时漏了 <code>setCharacterEncoding(&quot;UTF-8&quot;)</code></td></tr><tr><td>启动报 <code>WeakKeyException</code></td><td>JWT 密钥不足 32 字节</td></tr><tr><td>运行时报 <code>Unable to discover an implementation</code></td><td>jjwt 只引了 <code>jjwt-api</code>，缺 <code>jjwt-impl</code></td></tr><tr><td>前端跨域配置失效</td><td>引入 Security 后 CORS 必须配在 Security 里（<code>CorsConfigurationSource</code>），<code>WebMvcConfigurer#addCorsMappings</code> 会与它冲突产生重复响应头</td></tr><tr><td>启动日志出现 <code>UserDetailsService beans will not be used...</code> 的 WARN</td><td>手动声明了 <code>AuthenticationProvider</code> Bean，自动配置退让了。删掉自己的 Provider，交给自动配置</td></tr><tr><td>MockMvc 测试全部 401</td><td>缺 <code>spring-boot-starter-security-test</code>；或请求没加 <code>.with(user(...))</code></td></tr><tr><td><code>@AuthenticationPrincipal</code> 注入 null</td><td>测试里传的主体类型与 Controller 声明的类型不一致</td></tr><tr><td>改了角色但接口权限没变</td><td>令牌里存的是签发时的角色，要等令牌过期或重新登录</td></tr><tr><td>想让用户立刻下线却做不到</td><td>无状态令牌的固有限制，需引入 refreshToken + 黑名单或改用会话认证</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>安全层完成，接口可以交付了。第 6 篇回到数据这一侧，对照官方的 Data 章节把案例项目的数据访问层讲透：DataSource 与连接池配置、JPA 实体映射的细节（关联、级联、乐观锁）、事务的传播与失效场景、分页与 N+1 问题的排查，以及把 JPA 换成 MyBatis-Plus 3.5.17 的完整对照实现。</p></blockquote>',3)])])}const _=e(c,[["render",a]]);export{p as __pageData,_ as default};
